import { createRouter, createWebHistory } from "vue-router"
import Home from "./views/HomeView.vue" // eager: part of the initial chunk

const router = createRouter({
  history: createWebHistory(),
  routes: [
    { path: "/", component: Home },
    // Lazy routes: each gets its own chunk, fetched on first navigation.
    { path: "/dashboard", component: () => import("./views/DashboardView.vue") },
    { path: "/admin", component: () => import("./views/AdminView.vue") },
    // Nested splitting: a heavy child loads only when its tab is opened.
    {
      path: "/reports",
      component: () => import("./views/ReportsView.vue"),
      children: [
        {
          path: "charts",
          component: () => import("./views/ReportsCharts.vue") // chart lib lives here
        }
      ]
    }
  ]
})

export default router

// The chart library is imported inside ReportsCharts.vue, so users who
// never open /reports/charts never download it.
